type Pending = { kind: "pending"; items: Item[] };
type Paid    = { kind: "paid"; items: Item[]; paymentId: string };

function pay(o: Pending, p: Payment): Paid {
    return { ...o, kind: "paid", paymentId: p.id };
}
// ship(paid) typechecks; ship(pending) is an error: Pending is not assignable to Paid

type State = Partial<{ name: true }>;
class SafeUserBuilder<S extends State = {}> {
    setName<T extends string>(name: T): SafeUserBuilder<S & { name: true }> {
        this.user.name = name;
        return this as unknown as SafeUserBuilder<S & { name: true }>;
    }
    build(this: SafeUserBuilder<{ name: true }>): User { return this.user; }
}
// build() before setName() does not typecheck

